        rs, cs = panels[i, j]
        return {(a, b) for a, r in enumerate(rs) for b, c in enumerate(cs)
                if g[r][c] == color}

    def reflect(shape, width):
        return {(a, width - 1 - b) for a, b in shape}

    for color in colors:
        # Identify the adjacent panel pair that contains mirrored copies.
        best_pair = None
        best_score = -1
        best_occupancy = -1

        for j in range(nc - 1):
            score = occupancy = 0
            for i in range(nr):
                if (i, j) not in panels or (i, j + 1) not in panels:
                    continue
                left, right = get(i, j, color), get(i, j + 1, color)
                occupancy += bool(left) + bool(right)
                width = len(panels[i, j][1])
                if left and right and len(panels[i, j + 1][1]) == width:
                    if reflect(left, width) == right:
                        score += 1
            if (score, occupancy) > (best_score, best_occupancy):
                best_score, best_occupancy = score, occupancy
                best_pair = j

